#include <Servo.h> 
#define PIN_servo   3   // servo signal pin
#define BUTTON_PIN  2   // button pin
Servo myservo;
bool button_state;
int servoPos = __;      // start at one end of the range
void setup() {  
  myservo.attach(PIN_servo);  
  myservo.write(servoPos);  
  pinMode(__, __);
}
void loop() {  
  button_state = digitalRead(BUTTON_PIN);  
  if (button_state == __) {        // INPUT_PULLUP: pressed = LOW
    if (servoPos == __) {          // flip to the opposite end of the servo's range
      servoPos = __;    
    } 
    else {      
      servoPos = __;    
    }    
    myservo.write(servoPos);    // wait for the button to be released so one click = one move    
    while (button_state == __) {      
      delay(50);      
      button_state = __;    
    }  
  }
}
#include <Servo.h> 
#define PIN_servo   3   // servo signal pin
#define BUTTON_PIN  2   // button pin
